import sqlite3
import secrets
from fastapi import FastAPI, HTTPException, Query
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel, EmailStr, conint

# ---------- App and custom exception handling ----------
app = FastAPI()

@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request, exc):
    return JSONResponse(status_code=400, content={"detail": "Invalid input"})

# ---------- Database setup ----------
DB_FILE = "db.sqlite3"

def init_db():
    conn = sqlite3.connect(DB_FILE)
    try:
        conn.execute(
            """CREATE TABLE IF NOT EXISTS submissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL,
                count INTEGER NOT NULL,
                deletion_token TEXT NOT NULL UNIQUE
            )"""
        )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_token ON submissions(deletion_token)")
        conn.commit()
    finally:
        conn.close()

@app.on_event("startup")
def startup():
    init_db()

# ---------- Request model ----------
class SubmissionRequest(BaseModel):
    email: EmailStr
    count: conint(ge=0)  # non‑negative integer

# ---------- Utility to insert a new submission ----------
def insert_submission(email: str, count: int) -> str:
    """Insert a new submission and return its deletion token.
    Handles the astronomically unlikely token collision with a retry loop."""
    while True:
        token = secrets.token_urlsafe(32)
        try:
            conn = sqlite3.connect(DB_FILE)
            conn.execute(
                "INSERT INTO submissions (email, count, deletion_token) VALUES (?, ?, ?)",
                (email, count, token)
            )
            conn.commit()
            return token
        except sqlite3.IntegrityError:
            # duplicate token – try again
            pass
        finally:
            conn.close()

# ---------- Endpoints ----------
@app.post("/submissions", status_code=201)
def submit_observation(body: SubmissionRequest):
    token = insert_submission(body.email, body.count)
    return {"deletion_token": token}

@app.delete("/submissions")
def delete_submission(deletion_token: str = Query(..., description="Deletion token issued at submission time")):
    if not deletion_token.strip():
        raise HTTPException(status_code=400, detail="Invalid deletion token")

    conn = sqlite3.connect(DB_FILE)
    try:
        cur = conn.cursor()
        cur.execute("SELECT id FROM submissions WHERE deletion_token = ?", (deletion_token,))
        row = cur.fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Deletion token not found")

        cur.execute("DELETE FROM submissions WHERE id = ?", (row[0],))
        conn.commit()
        return {"detail": "Submission deleted"}
    finally:
        conn.close()

@app.get("/total")
def get_total():
    conn = sqlite3.connect(DB_FILE)
    try:
        cur = conn.cursor()
        cur.execute("SELECT COALESCE(SUM(count), 0) FROM submissions")
        total = cur.fetchone()[0]
        return {"total": total}
    finally:
        conn.close()

# ---------- Run ----------
if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)
